describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies using original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100
          new FixedAmountDiscountPolicy(200), // 200
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-50)).toBe(0);
    });

    it("defaults to sum mode when mode is omitted", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      // sum: 10% of 1000 = 100, plus 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negativeMock = { computeDiscountCents: () => -50 };
      const composite = new CompositeDiscountPolicy(
        [negativeMock, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100, remaining 900
          new PercentageDiscountPolicy(10), // 10% of 900 = 90
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("chain mode ordering affects result", () => {
      const composite1 = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(200), // 200 off 1000 → remaining 800
          new PercentageDiscountPolicy(10),    // 10% of 800 = 80
        ],
        "chain",
      );
      const composite2 = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10),    // 10% of 1000 = 100, remaining 900
          new FixedAmountDiscountPolicy(200),  // min(200, 900) = 200
        ],
        "chain",
      );
      expect(composite1.computeDiscountCents(1000)).toBe(280);
      expect(composite2.computeDiscountCents(1000)).toBe(300);
    });

    it("caps each step to remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(800), // 800 off 1000 → remaining 200
          new FixedAmountDiscountPolicy(500), // min(500, 200) = 200
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal in chain mode", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child results to 0 in chain mode", () => {
      const negativeMock = { computeDiscountCents: () => -100 };
      const composite = new CompositeDiscountPolicy(
        [negativeMock, new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // negative → clamped to 0, remaining still 1000; then min(200,1000)=200
      expect(composite.computeDiscountCents(1000)).toBe(200);
    });
  });
});

