function product(overrides: Partial<Product> & { id: string }): Product {
  return {
    name: overrides.id,
    unitPriceCents: 1000,
    ...overrides,
  };
}

describe("Cart – line management", () => {
  it("adds a product and tracks quantity", () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 3);
    expect(cart.itemCount).toBe(3);
  });

  it("merges quantities when adding the same product twice", () => {
    const cart = new Cart();
    const p = product({ id: "a" });
    cart.add(p, 2);
    cart.add(p, 5);
    expect(cart.itemCount).toBe(7);
  });

  it("rejects non-positive quantity on add", () => {
    const cart = new Cart();
    expect(() => cart.add(product({ id: "a" }), 0)).toThrow(RangeError);
    expect(() => cart.add(product({ id: "a" }), -1)).toThrow(RangeError);
    expect(() => cart.add(product({ id: "a" }), 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    const cart = new Cart();
    expect(() =>
      cart.add(product({ id: "a", unitPriceCents: -1 }), 1),
    ).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 3);
    cart.updateQuantity("a", 10);
    expect(cart.itemCount).toBe(10);
  });

  it("updateQuantity to 0 removes the product", () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 5);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.remove("a")).toBe(false);
  });

  it("updateQuantity rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("x", 1)).toThrow("not in the cart");
  });

  it("clear removes all products", () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 2);
    cart.add(product({ id: "b" }), 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns deep copies", () => {
    const cart = new Cart();
    cart.add(product({ id: "a", unitPriceCents: 500 }), 2);
    const snap = cart.snapshot();
    snap[0].product.unitPriceCents = 9999;
    snap[0].quantity = 99;
    // original cart is unaffected
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(1000);
  });
});

describe("Cart – pricing pipeline", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(product({ id: "a", unitPriceCents: 500 }), 3);
    cart.add(product({ id: "b", unitPriceCents: 1200 }), 2);
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(500 * 3 + 1200 * 2);
  });

  it("returns zero totals for empty cart", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount policy and clamps to [0, subtotal]", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product({ id: "a", unitPriceCents: 1000 }), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(300);
    expect(totals.totalCents).toBe(700);
  });

  it("clamps over-subtotal discount down to subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(9999),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product({ id: "a", unitPriceCents: 500 }), 1);
    expect(cart.totals().discountCents).toBe(500);
  });

  it("clamps negative discount to 0", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product({ id: "a", unitPriceCents: 500 }), 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("computes tax on discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
    cart.add(product({ id: "a", unitPriceCents: 1000 }), 1);
    const totals = cart.totals();
    // discounted subtotal = 800
    expect(tax.computeTaxCents).toHaveBeenCalledWith(800, "US");
    expect(totals.taxCents).toBe(80);
  });

  it("uses configured region for tax", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(product({ id: "a" }), 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "FR");
  });

  it("passes lines and discounted subtotal to shipping calculator", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
    });
    cart.add(product({ id: "a", unitPriceCents: 1000 }), 1);
    const totals = cart.totals();
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      900, // discounted subtotal
    );
    expect(totals.shippingCents).toBe(599);
    // total = discountedSubtotal + tax + shipping = 900 + 0 + 599
    expect(totals.totalCents).toBe(1499);
  });

  it("clamps negative tax to 0", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(product({ id: "a" }), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(product({ id: "a" }), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("total = discountedSubtotal + tax + shipping", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(160),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(product({ id: "a", unitPriceCents: 2000 }), 1);
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(2000);
    expect(totals.discountCents).toBe(200);
    // discounted = 1800, tax=160, shipping=500
    expect(totals.totalCents).toBe(1800 + 160 + 500);
  });
});

describe("Cart – checkout()", () => {
  it("returns totals and lines for simple checkout", async () => {
    const cart = new Cart();
    cart.add(product({ id: "a", unitPriceCents: 500 }), 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0].product.id).toBe("a");
  });

  it("refreshes prices via priceFetcher before computing totals", async () => {
    const cart = new Cart();
    cart.add(product({ id: "a", unitPriceCents: 500 }), 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(750),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    expect(result.totals.subtotalCents).toBe(1500); // 750 * 2
  });

  it("checks inventory and throws InventoryError on denial", async () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
        reason: "low stock",
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(5);
      expect(invErr.available).toBe(2);
      expect(invErr.message).toBe("low stock");
    }
  });

  it("throws InventoryError on partial-stock denial (available=true but quantity < requested)", async () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(10);
      expect(invErr.available).toBe(3);
    }
  });

  it("succeeds when inventory is fully available", async () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax when provided", async () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
      region: "US-CA",
    });
    cart.add(product({ id: "a", unitPriceCents: 1000 }), 1);
    const result = await cart.checkout({ asyncTaxProvider });
    // subtotal=1000, discount=100, discountedSubtotal=900
    // tax = floor(900 * 0.1) = 90
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    expect(result.totals.taxCents).toBe(90);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(900 + 90 + 500);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
    };
    const cart = new Cart();
    cart.add(product({ id: "a" }), 1);
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "rate service down",
    );
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price API down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price API down",
    );
  });

  it("combines priceFetcher, inventoryChecker, and asyncTaxProvider", async () => {
    const cart = new Cart({
      region: "US",
    });
    cart.add(product({ id: "a", unitPriceCents: 500 }), 2);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(600),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.05),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });
    // refreshed: 600 * 2 = 1200 subtotal
    expect(result.totals.subtotalCents).toBe(1200);
    // no discount configured, so discountCents=0
    expect(result.totals.discountCents).toBe(0);
    // tax = floor(1200 * 0.05) = 60
    expect(result.totals.taxCents).toBe(60);
    expect(result.totals.totalCents).toBe(1200 + 60);
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
  });

  it("first failing line wins in inventory check", async () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 1);
    cart.add(product({ id: "b" }), 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({ available: false, reason: "discontinued" }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).productId).toBe("b");
    }
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 10000, -50])(
    "returns 0 for subtotal %i",
    (subtotal) => {
      expect(policy.computeDiscountCents(subtotal)).toBe(0);
    },
  );
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects out-of-range percent %s",
      (percent) => {
        expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])(
      "accepts valid percent %i",
      (percent) => {
        expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
      },
    );
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 1000 = 100", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1000)).toBe(100);
    });

    it("rounds down to nearest cent (10% of 1001 = 100)", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1001)).toBe(100);
    });

    it("100% discount equals subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% discount returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("handles large subtotal", () => {
      const policy = new PercentageDiscountPolicy(15);
      // 15% of 999999 = 149999.85 → floor to 149999
      expect(policy.computeDiscountCents(999999)).toBe(149999);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, -100])(
      "rejects negative amountCents %i",
      (amount) => {
        expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
      },
    );

    it("rejects non-integer amountCents", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero amountCents", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(200)).toBe(200);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns exact subtotal when amount equals subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies using original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100
          new FixedAmountDiscountPolicy(200), // 200
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-50)).toBe(0);
    });

    it("defaults to sum mode when mode is omitted", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      // sum: 10% of 1000 = 100, plus 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negativeMock = { computeDiscountCents: () => -50 };
      const composite = new CompositeDiscountPolicy(
        [negativeMock, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100, remaining 900
          new PercentageDiscountPolicy(10), // 10% of 900 = 90
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("chain mode ordering affects result", () => {
      const composite1 = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(200), // 200 off 1000 → remaining 800
          new PercentageDiscountPolicy(10),    // 10% of 800 = 80
        ],
        "chain",
      );
      const composite2 = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10),    // 10% of 1000 = 100, remaining 900
          new FixedAmountDiscountPolicy(200),  // min(200, 900) = 200
        ],
        "chain",
      );
      expect(composite1.computeDiscountCents(1000)).toBe(280);
      expect(composite2.computeDiscountCents(1000)).toBe(300);
    });

    it("caps each step to remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(800), // 800 off 1000 → remaining 200
          new FixedAmountDiscountPolicy(500), // min(500, 200) = 200
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal in chain mode", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child results to 0 in chain mode", () => {
      const negativeMock = { computeDiscountCents: () => -100 };
      const composite = new CompositeDiscountPolicy(
        [negativeMock, new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // negative → clamped to 0, remaining still 1000; then min(200,1000)=200
      expect(composite.computeDiscountCents(1000)).toBe(200);
    });
  });
});

